You need to create a function `parseSwiftFile` that takes a file path as input and returns a tuple containing the author's name and the creation date. The comments in the Swift file will be in the following format:

```swift
//  WelcomeViewController.swift
//  FMIPractice
//
//  Created by Spas Bilyarski on 31.10.19.
//  Copyright © 2019 bilyarski. All rights reserved.
//
```

The function should extract the author's name ("Spas Bilyarski") and the creation date ("31.10.19") and return them as a tuple.

Assume that the file will always contain the required comments in the specified format.

Example:
For the given Swift file "WelcomeViewController.swift" with the comments as shown above, the function call `parseSwiftFile("WelcomeViewController.swift")` should return the tuple `("Spas Bilyarski", "31.10.19")`.

output:
func parseSwiftFile(_ filePath: String) -> (String, String) {
    do {
        let fileContent = try String(contentsOfFile: filePath)
        let lines = fileContent.components(separatedBy: .newlines)

        var authorName: String = ""
        var creationDate: String = ""

        for line in lines {
            if line.contains("Created by") {
                let components = line.components(separatedBy: "by")
                if components.count > 1 {
                    authorName = components[1].trimmingCharacters(in: .whitespacesAndNewlines)
                }
            } else if line.contains("on") {
                let components = line.components(separatedBy: "on")
                if components.count > 1 {
                    creationDate = components[1].trimmingCharacters(in: .whitespacesAndNewlines)
                }
            }
        }

        return (authorName, creationDate)
    } catch {
        print("Error reading file: \(error)")
        return ("", "")
    }
}

