namespace IntegrationTest.Domain.Commands.Results
{
    public class InvoiceCommandResults
    {
        public List<InvoiceItem> Items { get; set; }

        public decimal CalculateTotalAmount(Dictionary<string, decimal> itemPrices)
        {
            decimal totalAmount = 0;

            foreach (var item in Items)
            {
                if (itemPrices.ContainsKey(item.Name))
                {
                    decimal itemAmount = itemPrices[item.Name] * item.Quantity;
                    totalAmount += itemAmount;
                }
                else
