function extractTableNames(sqlStatements) {
  const tableNames = [];
  const regex = /CREATE TABLE\s+(\w+)\s*\(/g;
  let match;

  while ((match = regex.exec(sqlStatements)) !== null) {
    tableNames.push(match[1]);
  }

  return tableNames;
}

