class EventManager {
    var eventMap: [MD2Event: [MD2Event]] = [:]

    // Add an event to the data structure
    func addEvent(event: MD2Event) {
        let eventType = event
        if eventMap[eventType] == nil {
            eventMap[eventType] = [event]
        } else {
            eventMap[eventType]?.append(event)
        }
    }

    // Remove an event from the data structure
    func removeEvent(event: MD2Event) {
        if let events = eventMap[event] {
            if let index = events.firstIndex(of: event) {
                eventMap[event]?.remove(at: index)
            }
        }
    }

    // Process events of a specific type
    func processEventsOfType(eventType: MD2Event) {
        if let events = eventMap[eventType] {
            print("Processing events of type \(eventType):")
            for event in events {
                print(event)
            }
        } else {
            print("No events of type \(eventType) to process.")
        }
    }
