function analyzePhpCode($codeSnippet) {
    $namespaces = [];
    $controllerClass = '';

    // Extract namespaces and class name from the code snippet
    $lines = explode("\n", $codeSnippet);
    foreach ($lines as $line) {
        if (strpos($line, 'use ') === 0) {
            $namespace = trim(str_replace(['use', ';'], '', $line));
            $namespaces[] = $namespace;
        } elseif (preg_match('/class (\w+) extends BaseController/', $line, $matches)) {
            $controllerClass = $matches[1];
        }
    }

    // Prepare the output
    $output = "Namespaces imported:\n";
    foreach ($namespaces as $namespace) {
        $output .= "- $namespace\n";
    }
    $output .= "\nController class name: $controllerClass";

    return $output;
}

