import os
import zipfile
import tarfile

class DatasetExtractor:
    def __init__(self, root, name):
        self.root = root
        self.name = name
        self.urls = []

    def extract_dataset(self):
        path = os.path.join(self.root, self.name)
        for url in self.urls:
            if isinstance(url, tuple):
                url, file_format = url
                if file_format == 'zip':
                    with zipfile.ZipFile(url, 'r') as zip_ref:
                        zip_ref.extractall(path)
                elif file_format == 'tar':
                    with tarfile.open(url, 'r') as tar_ref:
                        tar_ref.extractall(path)

    def check_dataset_existence(self, check=None):
        path = os.path.join(self.root, self.name)
        check = path if check is None else check
        return os.path.isdir(check)

