// Create a module registry to store available modules
struct ModuleRegistry {
    modules: Vec<Box<dyn Module>>,
}

impl ModuleRegistry {
    fn new() -> ModuleRegistry {
        ModuleRegistry { modules: Vec::new() }
    }

    fn register_module(&mut self, module: Box<dyn Module>) {
        self.modules.push(module);
    }

    fn get_module(&self, index: usize) -> Option<&Box<dyn Module>> {
        self.modules.get(index)
    }
}

// Define a client interface for accessing modules
pub struct ModuleClient {
    registry: ModuleRegistry,
}

impl ModuleClient {
    pub fn new() -> ModuleClient {
        ModuleClient {
            registry: ModuleRegistry::new(),
        }
    }

    pub fn register_module(&mut self, module: Box<dyn Module>) {
        self.registry.register_module(module);
    }

    pub fn use_module(&self, index: usize) {
        if let Some(module) = self.registry.get_module(index) {
            module.perform_action();
        } else {
            println!("Module not found");
        }
    }
}

fn main() {
    let mut client = ModuleClient::new();
    let sample_module = Box::new(SampleModule);
    client.register_module(sample_module);
    client.use_module(0);
}

