class Fibonacci:
    def fib_recurs_naive(self, n):
        if n <= 1:
            return n
        else:
            return self.fib_recurs_naive(n-1) + self.fib_recurs_naive(n-2)

    def fib_recurs_fast(self, n):
        memo = {}
        return self._fib_recurs_fast(n, memo)

    def _fib_recurs_fast(self, n, memo):
        if n in memo:
            return memo[n]
        if n <= 1:
            return n
        else:
            memo[n] = self._fib_recurs_fast(n-1, memo) + self._fib_recurs_fast(n-2, memo)
            return memo[n]

def main():
