public class JavaToDictionary {

    private final Collection<Class<?>> tcClasses;

    public JavaToDictionary(Collection<Class<?>> tcClasses) {
        this.tcClasses = tcClasses;
    }

    public void convertToDictionary() {
        TestDictionary testDictionary = new TestDictionary();
        ClassToDictionaryVisitor visitor = new ClassToDictionaryVisitor(testDictionary);

        for (Class<?> tcClass : tcClasses) {
            visitor.visit(tcClass);
        }

        JsonModelPersister persister = new JsonModelPersister();
        Path dictionaryFilePath = Paths.get("test_dictionary.json");

        try {
