import { Controller, Get, Param, Delete, Put, Body, HttpException, HttpStatus } from 'some-rest-framework';
import { Task, TaskService } from './taskService';

@Controller('/tasks')
class TaskController {
    constructor(private taskService: TaskService) {}

    @Get('/:id')
    getTaskById(@Param('id') id: string): Task {
        return this.taskService.getTaskById(id);
    }

    @Delete('/:id')
    deleteTask(@Param('id') id: string): void {
        this.taskService.deleteTask(id);
    }

    @Put('/:id/status')
    updateTaskStatus(@Param('id') id: string, @Body('status') status: string): Task {
        const validStatusValues = ['pending', 'in progress', 'completed'];
        if (!validStatusValues.includes(status)) {
            throw new HttpException('Invalid status value', HttpStatus.BAD_REQUEST);
        }

        const updatedTask = this.taskService.updateTaskStatus(id, status);
        if (!updatedTask) {
            throw new HttpException('Task not found', HttpStatus.NOT_FOUND);
        }

        return updatedTask;
    }
}

