function buildLanguageExtensionMap(defs: LanguageExtensionDefinitions): ExtensionToLanguageIdMap {
    const extensionMap: ExtensionToLanguageIdMap = new Map();

    for (const definition of defs) {
        for (const extension of definition.extensions) {
            if (extensionMap.has(extension)) {
