class ClassHandler:
    @staticmethod
    def normalize_definition(typedef):
        # Normalize the definition by ensuring it is in a standardized format
        normalized_typedef = {}
        for key, value in typedef.items():
            normalized_typedef[key.lower()] = value
        return normalized_typedef

    @staticmethod
    def decode_data(obj, typedef):
        # Decode the data based on the definition's arguments
        decoded_args = {}
        for prop, prop_def in typedef['properties'].items():
            if prop in obj:
                decoded_args[prop] = obj[prop]
        return decoded_args

    @staticmethod
    def instantiate_object(typedef, args):
        # Instantiate an object of the specified class using the decoded arguments
        class_name = typedef['class']
        class_instance = globals()[class_name]
        return class_instance(**args)

