func parseManifest(_ manifestContent: String) -> [String: Any] {
    var result: [String: Any] = [:]

    if let packageName = manifestContent.extractStringBetween("name: \"", "\"") {
        result["packageName"] = packageName
    }

    if let dependencies = manifestContent.extractStringsBetween("dependencies: [\"", "\"]") {
        result["dependencies"] = dependencies
    }

    if let testTargets = manifestContent.extractStringsBetween(".testTarget(name: \"", "\"") {
        result["testTargets"] = testTargets
    }

    return result
}

extension String {
    func extractStringBetween(_ start: String, _ end: String) -> String? {
        guard let startRange = range(of: start), let endRange = range(of: end, options: .backwards) else {
            return nil
        }
        let substringRange = index(startRange.upperBound, offsetBy: 0)..<endRange.lowerBound
        return String(self[substringRange])
    }

    func extractStringsBetween(_ start: String, _ end: String) -> [String]? {
        var results: [String] = []
        var searchStartIndex = startIndex
        while let rangeStart = range(of: start, range: searchStartIndex ..< endIndex),
              let rangeEnd = range(of: end, range: rangeStart.upperBound ..< endIndex) {
            let substringRange = rangeStart.upperBound ..< rangeEnd.lowerBound
            results.append(String(self[substringRange]))
            searchStartIndex = rangeEnd.upperBound
        }
        return results.isEmpty ? nil : results
    }
}

