#[derive(Debug, Default)]
pub struct Empty;

impl Empty {
    pub fn new() -> Self {
        Empty
    }
}

pub struct Stack<T> {
    elements: Vec<T>,
}

impl<T> Stack<T> {
    pub fn new() -> Self {
        Stack { elements: Vec::new() }
    }

    pub fn push(&mut self, item: T) {
        self.elements.push(item);
    }

    pub fn pop(&mut self) -> Option<T> {
        self.elements.pop()
    }

    pub fn peek(&self) -> Option<&T> {
        self.elements.last()
    }
}

fn main() {
    let mut stack: Stack<i32> = Stack::new();
    stack.push(5);
    stack.push(10);
    println!("{:?}", stack); // Output: [5, 10]
    println!("{:?}", stack.peek()); // Output: Some(10)
    println!("{:?}", stack.pop()); // Output: Some(10)
    println!("{:?}", stack); // Output: [5]
}

