            if 'les' in filename:
                categories['les-videos'].append(filename)
            if 'alm' in filename:
                categories['alm-videos'].append(filename)
            if not any(category in source_path for category in ['unh-rvat', 'NTNU-HAWT']) and 'les' not in filename and 'alm' not in filename:
                categories['other-videos'].append(filename)

    counts = {category: len(videos) for category, videos in categories.items()}

    for category, videos in categories.items():
        destination_folder = category.split('-')[0]  # Extract the category name for the destination folder
        for video in videos:
            source_file = os.path.join(os.path.dirname(file_paths[0]), f'{video}.ogv')
            destination_file = os.path.join('videos', destination_folder, f'{video}.ogv')
