class CallMonitor {
    callMonitoring?: boolean;
    callRecords: Map<string, number>; // Map to store call start times

    constructor() {
        this.callRecords = new Map();
    }

    // Enable or disable call monitoring
    setCallMonitoring(enable: boolean): void {
        this.callMonitoring = enable;
    }

    // Start tracking the duration of a call
    startCall(callId: string): void {
        if (this.callMonitoring) {
            this.callRecords.set(callId, Date.now()); // Record the start time of the call
        }
    }

    // End tracking the duration of a call
    endCall(callId: string): void {
        if (this.callMonitoring && this.callRecords.has(callId)) {
            const startTime = this.callRecords.get(callId) || 0;
            const duration = Date.now() - startTime; // Calculate the duration of the call
            console.log(`Call ${callId} duration: ${duration}ms`);
            this.callRecords.delete(callId); // Remove the call record
        }
    }
}

export default CallMonitor;

