def fileSystemNavigation(commands):
    current_directory = "/"
    output = []

    for command in commands:
        if command.startswith("cd "):
            directory = command[3:]
            if directory.startswith("/"):
                current_directory = directory
            else:
                current_directory += "/" + directory
        elif command == "pwd":
            output.append(current_directory)
        elif command == "ls":
            contents = " ".join(sorted(os.listdir(current_directory)))
            output.append(contents)

    return output

